// Second-pass enrichment: for every named building in each campus geojson,
// pre-fetch Wikipedia summary (photo + extract + url + built year + height)
// and bake it into the feature properties. No runtime Wikipedia calls after this.
//
// Run:
//   node scripts/enrich-campuses.mjs                 # all colleges
//   node scripts/enrich-campuses.mjs stanford-university  # one slug
//   node scripts/enrich-campuses.mjs --force         # re-enrich even buildings we've tried before

import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import path from 'node:path';
import { isRelevantMatch } from './wikipedia-match.mjs';

const CONCURRENCY = 4;
const BATCH_DIR = 'data/buildings';

// Quick map of slug → college name (for search context: "Hoover Tower Stanford")
const COLLEGE_NAME = {
  'harvard-university': 'Harvard',
  'stanford-university': 'Stanford',
  'mit': 'Massachusetts Institute of Technology',
  'yale-university': 'Yale',
  'princeton-university': 'Princeton',
  'columbia-university': 'Columbia',
  'university-of-pennsylvania': 'University of Pennsylvania',
  'brown-university': 'Brown',
  'duke-university': 'Duke',
  'northwestern-university': 'Northwestern',
  'university-of-chicago': 'University of Chicago',
  'caltech': 'Caltech',
  'johns-hopkins-university': 'Johns Hopkins',
  'cornell-university': 'Cornell',
  'rice-university': 'Rice',
  'vanderbilt-university': 'Vanderbilt',
  'university-of-notre-dame': 'Notre Dame',
  'georgetown-university': 'Georgetown',
  'uc-berkeley': 'UC Berkeley',
  'ucla': 'University of California Los Angeles',
  'uc-san-diego': 'UC San Diego',
  'uc-santa-barbara': 'UC Santa Barbara',
  'uc-davis': 'UC Davis',
  'uc-irvine': 'UC Irvine',
  'university-of-michigan': 'University of Michigan',
  'university-of-virginia': 'University of Virginia',
  'carnegie-mellon-university': 'Carnegie Mellon',
  'emory-university': 'Emory',
  'usc': 'University of Southern California',
  'nyu': 'New York University',
  'university-of-north-carolina': 'University of North Carolina',
  'university-of-georgia': 'University of Georgia',
  'university-of-texas-at-austin': 'University of Texas at Austin',
  'university-of-florida': 'University of Florida',
  'university-of-washington': 'University of Washington',
  'ohio-state-university': 'Ohio State',
  'university-of-wisconsin': 'University of Wisconsin',
  'university-of-arizona': 'University of Arizona',
  'boston-university': 'Boston University',
  'tulane-university': 'Tulane',
  'university-of-miami': 'University of Miami',
  'pepperdine-university': 'Pepperdine',
  'villanova-university': 'Villanova',
  'boston-college': 'Boston College',
  'tufts-university': 'Tufts',
  'northeastern-university': 'Northeastern',
  'wake-forest-university': 'Wake Forest',
  'george-washington-university': 'George Washington University',
  'university-of-rochester': 'University of Rochester',
  'case-western-reserve': 'Case Western Reserve',
  'lehigh-university': 'Lehigh',
  'university-of-colorado-boulder': 'University of Colorado Boulder',
  'university-of-utah': 'University of Utah',
  'brigham-young-university': 'Brigham Young University',
  'university-of-hawaii-at-manoa': 'University of Hawaii',
  'hawaii-pacific-university': 'Hawaii Pacific',
  'university-of-alaska-anchorage': 'University of Alaska Anchorage',
  'university-of-alaska-fairbanks': 'University of Alaska Fairbanks',
};

const UA = 'usa-college-map/1.0 (https://github.com/Counselor-Sophie/usa-college-map)';

async function fetchJSON(url) {
  const res = await fetch(url, { headers: { 'User-Agent': UA, 'Accept': 'application/json' } });
  if (!res.ok) return null;
  return await res.json();
}

function extractWikipediaTitle(tags) {
  if (typeof tags.wikipedia !== 'string') return null;
  const parts = tags.wikipedia.split(':');
  if (parts.length >= 2 && parts[0] === 'en') return parts.slice(1).join(':').replace(/ /g, '_');
  return null;
}

async function titleFromWikidata(qid) {
  if (!qid) return null;
  const data = await fetchJSON(`https://www.wikidata.org/wiki/Special:EntityData/${qid}.json`);
  const entity = data?.entities?.[qid];
  const sitelink = entity?.sitelinks?.enwiki;
  return sitelink?.title?.replace(/ /g, '_') || null;
}

async function fetchWikipediaSummary(title) {
  const url = `https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(title)}`;
  const data = await fetchJSON(url);
  if (!data || data.type === 'disambiguation' || data.title === 'Not found.') return null;
  return data;
}

async function searchWikipedia(query, collegeName) {
  // Search only with college context — building names alone are too ambiguous.
  const url = `https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(`${query} ${collegeName}`)}&srlimit=3&format=json&origin=*`;
  const data = await fetchJSON(url);
  const hits = data?.query?.search || [];
  if (!hits.length) return null;

  // Verify each candidate by fetching its summary.
  for (const hit of hits) {
    const title = hit.title.replace(/ /g, '_');
    const summary = await fetchWikipediaSummary(title);
    if (!summary) continue;
    if (isRelevantMatch(summary, query, collegeName)) {
      return { title, summary };
    }
  }
  return null;
}

async function fetchWikidataFacts(qid) {
  if (!qid) return {};
  const data = await fetchJSON(`https://www.wikidata.org/wiki/Special:EntityData/${qid}.json`);
  const entity = data?.entities?.[qid];
  const claims = entity?.claims || {};
  const facts = {};
  const inception = claims.P571?.[0]?.mainsnak?.datavalue?.value?.time;
  if (inception) facts.built = inception.split('-')[0].replace(/^\+/, '');
  const height = claims.P2048?.[0]?.mainsnak?.datavalue?.value;
  if (height?.amount) facts.height = `${Math.round(Number(height.amount))} m`;
  return facts;
}

async function enrichBuilding(feature, collegeName) {
  const t = feature.properties || {};
  if (!t.name) return null;

  // Prefer explicit OSM tags (trust them)
  let title = extractWikipediaTitle(t);
  let summary = null;
  if (!title && t.wikidata) title = await titleFromWikidata(t.wikidata);
  if (title) summary = await fetchWikipediaSummary(title);

  // Otherwise search with stricter relevance (article must mention the college)
  if (!summary) {
    const hit = await searchWikipedia(t.name, collegeName);
    if (hit) { title = hit.title; summary = hit.summary; }
  }

  if (!summary) return { _wikiTried: true };

  const qid = summary.wikibase_item || t.wikidata;
  const facts = await fetchWikidataFacts(qid);

  return {
    _wikiTried: true,
    wikiTitle: title,
    wikiDescription: summary.description || null,
    wikiExtract: summary.extract || null,
    wikiUrl: summary.content_urls?.desktop?.page || null,
    wikiPhoto: summary.originalimage?.source || summary.thumbnail?.source || null,
    wikiBuilt: facts.built || null,
    wikiHeight: facts.height || null,
  };
}

async function enrichCampus(slug, force) {
  const file = path.join(BATCH_DIR, `${slug}.geojson`);
  let data;
  try {
    data = JSON.parse(readFileSync(file, 'utf8'));
  } catch {
    console.error(`  ! couldn't read ${file}`);
    return;
  }

  const collegeName = COLLEGE_NAME[slug] || slug;
  const toEnrich = data.features.filter((f) => {
    const p = f.properties || {};
    if (!p.name) return false;
    if (!force && p._wikiTried) return false;
    return true;
  });

  if (!toEnrich.length) {
    console.log(`  ✓ ${slug}: nothing to enrich`);
    return;
  }

  console.log(`  → ${slug}: enriching ${toEnrich.length}/${data.features.length} named buildings...`);

  const WIKI_FIELDS = ['wikiTitle','wikiDescription','wikiExtract','wikiUrl','wikiPhoto','wikiBuilt','wikiHeight'];
  let succeeded = 0;
  let idx = 0;
  const workers = Array.from({ length: CONCURRENCY }, () => (async () => {
    while (idx < toEnrich.length) {
      const feature = toEnrich[idx++];
      // Strip any stale wiki fields first so a now-rejected match gets cleared.
      for (const k of WIKI_FIELDS) delete feature.properties[k];
      try {
        const enrichment = await enrichBuilding(feature, collegeName);
        if (enrichment) {
          Object.assign(feature.properties, enrichment);
          if (enrichment.wikiTitle) succeeded++;
        }
      } catch (err) {
        feature.properties._wikiTried = true;
      }
    }
  })());
  await Promise.all(workers);

  writeFileSync(file, JSON.stringify(data));
  console.log(`  ✓ ${slug}: ${succeeded}/${toEnrich.length} buildings matched a Wikipedia article`);
}

async function main() {
  const args = process.argv.slice(2);
  const force = args.includes('--force');
  const slugs = args.filter((a) => !a.startsWith('--'));

  const targets = slugs.length
    ? slugs
    : readdirSync(BATCH_DIR)
        .filter((f) => f.endsWith('.geojson'))
        .map((f) => f.replace(/\.geojson$/, ''));

  console.log(`Enriching ${targets.length} campus(es) (force=${force})...`);
  for (const slug of targets) {
    await enrichCampus(slug, force);
  }
  console.log('Done.');
}

main().catch((err) => { console.error(err); process.exit(1); });

// Conservative matching for Wikipedia search results. Explicit OSM wikipedia and
// wikidata tags bypass this heuristic because those references are authoritative.

const PLACE_WORDS = /\b(building|tower|hall|library|centre|center|stadium|union|church|cathedral|chapel|museum|garden|pavilion|wing|annex|dormitory|residence|hospital|arena|auditorium|theatre|theater|campus|quadrangle|quad|laboratory|observatory|gymnasium|complex|institute|gallery|lab|mall|structure|facility|bridge|statue|memorial|monument|park|plaza|school|academy)\b/i;

const NON_PLACE_DESCRIPTORS = /\b(politician|businessman|businesswoman|entrepreneur|philanthropist|artist|painter|sculptor|author|writer|novelist|journalist|director|architect|professor|scientist|physicist|mathematician|chemist|biologist|economist|musician|singer|actor|actress|judge|lawyer|philosopher|theologian|athlete|football|basketball|baseball|tennis|boxer|olympian|coach|cardinal|horse|farm|ranch|film|movie|novel|song|album|character|species|ship|aircraft|vehicle|company|corporation|organization|foundation|fraternity|sorority|band|team|faction)\b/i;

const GENERIC_COLLEGE_WORDS = new Set([
  'university', 'college', 'institute', 'school', 'the', 'of', 'at',
]);
const ACRONYM_STOP_WORDS = new Set(['the', 'of', 'at']);

const GENERIC_BUILDING_WORDS = new Set([
  'academy', 'annex', 'arena', 'auditorium', 'building', 'campus',
  'cathedral', 'center', 'centre', 'chapel', 'church', 'complex',
  'dormitory', 'facility', 'gallery', 'garden', 'gymnasium', 'hall',
  'hospital', 'house', 'institute', 'laboratory', 'library', 'mall',
  'memorial', 'museum', 'observatory', 'park', 'pavilion', 'plaza',
  'quadrangle', 'residence', 'school', 'stadium', 'structure', 'theater',
  'theatre', 'tower', 'union', 'wing',
]);

function normalize(value) {
  return String(value || '')
    .toLocaleLowerCase('en-US')
    .replace(/[_\p{P}\p{S}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function includesPhrase(text, phrase) {
  return phrase.length > 0 && ` ${text} `.includes(` ${phrase} `);
}

// Is this search result about a specific building on this college's campus?
export function isRelevantMatch(summary, buildingName, collegeName) {
  const title = normalize(summary.title);
  const extract = normalize(summary.extract);
  const description = normalize(summary.description);
  const normalizedBuilding = normalize(buildingName);
  const normalizedCollege = normalize(collegeName);

  if (NON_PLACE_DESCRIPTORS.test(description)) return false;
  if (title === normalizedCollege) return false;

  const looksLikePlace =
    PLACE_WORDS.test(title) ||
    PLACE_WORDS.test(description) ||
    /\b(is a building|is an academic|was built|was completed|was constructed|was designed|is located on|is housed in|is the main|opened in)\b/i.test(extract.slice(0, 400));
  if (!looksLikePlace) return false;

  const articleText = `${title} ${description} ${extract}`;
  const articleWords = new Set(articleText.split(' ').filter(Boolean));
  const collegeTokens = normalizedCollege
    .split(' ')
    .filter((word) => word.length > 2 && !GENERIC_COLLEGE_WORDS.has(word));
  const collegeInitials = normalizedCollege
    .split(' ')
    .filter((word) => word.length > 0 && !ACRONYM_STOP_WORDS.has(word))
    .map((word) => word[0])
    .join('');
  const collegeMentioned =
    includesPhrase(articleText, normalizedCollege) ||
    (collegeTokens.length > 0 && collegeTokens.every((word) => articleWords.has(word))) ||
    (collegeInitials.length >= 3 && articleWords.has(collegeInitials));
  if (!collegeMentioned) return false;

  const titleWords = new Set(title.split(' ').filter(Boolean));
  const distinctiveBuildingTokens = normalizedBuilding
    .split(' ')
    .filter((word) => word.length > 3 && !GENERIC_BUILDING_WORDS.has(word));
  const exactBuildingMention =
    includesPhrase(title, normalizedBuilding) ||
    includesPhrase(extract, normalizedBuilding);
  const titleHasDistinctiveToken = distinctiveBuildingTokens.some((word) =>
    titleWords.has(word)
  );

  return exactBuildingMention || titleHasDistinctiveToken;
}

import assert from 'node:assert/strict';
import test from 'node:test';

import { isRelevantMatch } from '../scripts/wikipedia-match.mjs';

test('accepts a specific campus building with college evidence', () => {
  const summary = {
    title: 'Hoover Tower',
    description: '285-foot structure on the campus of Stanford University',
    extract: 'Hoover Tower is a structure on the campus of Stanford University.',
  };

  assert.equal(isRelevantMatch(summary, 'Hoover Tower', 'Stanford University'), true);
});

test('rejects an unrelated building with the same name', () => {
  const summary = {
    title: 'Murray House',
    description: 'Building in Stanley, Hong Kong',
    extract: 'Murray House is a Victorian-era building in Stanley, Hong Kong.',
  };

  assert.equal(isRelevantMatch(summary, 'Murray House', 'Stanford University'), false);
});

test('rejects a person whose name contains the building name', () => {
  const summary = {
    title: 'Jesús Huerta de Soto',
    description: 'Spanish economist of the Austrian School',
    extract: 'Jesús Huerta de Soto is a professor in Madrid, Spain.',
  };

  assert.equal(isRelevantMatch(summary, 'Soto', 'Stanford University'), false);
});

test('rejects a generic building name matched to a different campus landmark', () => {
  const summary = {
    title: 'Hoover Tower',
    description: 'Tower on the campus of Stanford University',
    extract: 'Hoover Tower is located at Stanford University.',
  };

  assert.equal(isRelevantMatch(summary, 'Tower Building', 'Stanford University'), false);
});

test('matches short college names as words instead of substrings', () => {
  const summary = {
    title: 'Committee Hall',
    description: 'Academic building',
    extract: 'Committee Hall is the main building for a regional committee.',
  };

  assert.equal(isRelevantMatch(summary, 'Committee Hall', 'MIT'), false);
});

test('accepts a college acronym derived from its full name', () => {
  const summary = {
    title: 'Great Dome',
    description: 'Academic building at MIT',
    extract: 'The Great Dome is a landmark on the MIT campus.',
  };

  assert.equal(
    isRelevantMatch(summary, 'Great Dome', 'Massachusetts Institute of Technology'),
    true
  );
});
